        ).detect()
        guard
            let effectiveWorkerSecret = resolveWorkerSharedSecret(
                cliWorkerSecret: workerSecret,
                environment: env
            )
        else {
            writeToStandardError("Error: missing runner secret. Use --worker-secret or set RUNNER_SHARED_SECRET.\n")
            throw ExitCode.failure
        }

