            apiBaseURL: baseURL,
            workerID: workerID,
            workerSecret: effectiveWorkerSecret,
            heartbeatRetryPolicy: .heartbeat(config: config),
            resultUploadRetryPolicy: .resultUpload(config: config)
        )
